def servicio_necesario(tipo_entrada, necesita_respuesta_hablada):
    pasos = []
    if tipo_entrada == "audio":
        pasos.append("speech_to_text")
    pasos.append("analisis_de_texto")
    if necesita_respuesta_hablada:
        pasos.append("text_to_speech")
    return pasos

casos = [
    ("audio", True),
    ("texto", False),
    ("audio", False),
]

for tipo_entrada, necesita_voz in casos:
    print(f"{tipo_entrada}/voz={necesita_voz} -> {servicio_necesario(tipo_entrada, necesita_voz)}")
